import {
  google,
  type GoogleLanguageModelInteractionsOptions,
  type GoogleInteractionsVideoOptions,
} from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStreamResponse,
  streamText,
  toUIMessageStream,
  type UIMessage,
} from 'ai';

export const maxDuration = 300;

function findLatestInteractionId(messages: UIMessage[]): string | undefined {
  for (let index = messages.length - 1; index >= 0; index--) {
    const message = messages[index];
    if (message.role !== 'assistant') {
      continue;
    }
    for (const part of message.parts) {
      const interactionId = (
        part as {
          providerMetadata?: { google?: { interactionId?: unknown } };
        }
      ).providerMetadata?.google?.interactionId;
      if (typeof interactionId === 'string') {
        return interactionId;
      }
    }
  }
}

function addAgenticVideoProcessing(messages: UIMessage[]): UIMessage[] {
  return messages.map(message => ({
    ...message,
    parts: message.parts.map(part => {
      if (part.type !== 'file' || !part.mediaType.startsWith('video/')) {
        return part;
      }

      return {
        ...part,
        providerMetadata: {
          ...part.providerMetadata,
          google: {
            ...part.providerMetadata?.google,
            processing: 'agentic',
          } satisfies GoogleInteractionsVideoOptions,
        },
      };
    }),
  }));
}

export async function POST(req: Request) {
  const { messages }: { messages: UIMessage[] } = await req.json();
  const previousInteractionId = findLatestInteractionId(messages);
  const modelMessages = await convertToModelMessages(
    addAgenticVideoProcessing(messages),
  );
  const latestUserMessage = modelMessages.findLast(
    message => message.role === 'user',
  );

  const result = streamText({
    model: google.interactions('gemini-3.8-flash'),
    messages:
      previousInteractionId != null && latestUserMessage != null
        ? [latestUserMessage]
        : modelMessages,
    abortSignal: req.signal,
    providerOptions: {
      google: {
        store: true,
        thinkingSummaries: 'auto',
        ...(previousInteractionId != null ? { previousInteractionId } : {}),
      } satisfies GoogleLanguageModelInteractionsOptions,
    },
  });

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({ stream: result.stream }),
  });
}

import type { ElicitationResponse } from './types';

// Use globalThis to ensure the Map is shared across all Next.js API routes
// This prevents issues with module reloading in development
declare global {
  var pendingElicitations:
    | Map<
        string,
        {
          resolve: (response: ElicitationResponse) => void;
          reject: (error: Error) => void;
          createdAt: number;
          timeoutId: NodeJS.Timeout;
        }
      >
    | undefined;
}

// Store pending elicitation requests with their resolvers
const pendingElicitations =
  globalThis.pendingElicitations ??
  new Map<
    string,
    {
      resolve: (response: ElicitationResponse) => void;
      reject: (error: Error) => void;
      createdAt: number;
      timeoutId: NodeJS.Timeout;
    }
  >();

// Persist to globalThis
globalThis.pendingElicitations = pendingElicitations;

// Cleanup old/stale elicitations periodically
function cleanupStaleElicitations() {
  const now = Date.now();
  const staleThreshold = 10 * 60 * 1000; // 10 minutes

  const entries = Array.from(pendingElicitations.entries());
  for (const [id, data] of entries) {
    if (now - data.createdAt > staleThreshold) {
      console.log('[store] Cleaning up stale elicitation:', id);
      clearTimeout(data.timeoutId);
      pendingElicitations.delete(id);
    }
  }
}

// Run cleanup every minute
setInterval(cleanupStaleElicitations, 60 * 1000);

export function createPendingElicitation(
  id: string,
): Promise<ElicitationResponse> {
  console.log('[store] Creating pending elicitation:', id);
  console.log(
    '[store] Current pending IDs:',
    Array.from(pendingElicitations.keys()),
  );
  console.log('[store] Current pending count:', pendingElicitations.size);

  // Check if this ID already exists (shouldn't happen, but handle it)
  if (pendingElicitations.has(id)) {
    console.warn('[store] WARNING: Elicitation ID already exists:', id);
    const existing = pendingElicitations.get(id);
    if (existing) {
      clearTimeout(existing.timeoutId);
      pendingElicitations.delete(id);
    }
  }

  return new Promise<ElicitationResponse>((resolve, reject) => {
    // Set a timeout to prevent hanging indefinitely (60 seconds to match MCP timeout)
    const timeoutId = setTimeout(() => {
      if (pendingElicitations.has(id)) {
        console.log('[store] Timeout for elicitation:', id);
        pendingElicitations.delete(id);
        reject(new Error('Request timed out'));
      }
    }, 60 * 1000);

    pendingElicitations.set(id, {
      resolve,
      reject,
      createdAt: Date.now(),
      timeoutId,
    });
    console.log('[store] Added to map. New count:', pendingElicitations.size);
  });
}

export function resolvePendingElicitation(
  response: ElicitationResponse,
): boolean {
  console.log('[store] Attempting to resolve:', response.id);
  console.log(
    '[store] Current pending IDs:',
    Array.from(pendingElicitations.keys()),
  );

  const pending = pendingElicitations.get(response.id);

  if (!pending) {
    console.log('[store] Not found in map!');
    return false;
  }

  console.log('[store] Found! Resolving...');
  clearTimeout(pending.timeoutId);
  pending.resolve(response);
  pendingElicitations.delete(response.id);
  console.log(
    '[store] Resolved and removed. Remaining count:',
    pendingElicitations.size,
  );
  return true;
}

export function rejectPendingElicitation(id: string, error: Error): boolean {
  console.log('[store] Attempting to reject:', id);
  const pending = pendingElicitations.get(id);

  if (!pending) {
    console.log('[store] Not found in map for rejection!');
    return false;
  }

  console.log('[store] Found! Rejecting...');
  clearTimeout(pending.timeoutId);
  pending.reject(error);
  pendingElicitations.delete(id);
  console.log(
    '[store] Rejected and removed. Remaining count:',
    pendingElicitations.size,
  );
  return true;
}

import { openai } from '@ai-sdk/openai';
import {
  createUIMessageStreamResponse,
  streamText,
  createUIMessageStream,
  convertToModelMessages,
  isStepCount,
  toUIMessageStream,
} from 'ai';
import { createMCPClient, ElicitationRequestSchema } from '@ai-sdk/mcp';
import type { MCPElicitationUIMessage } from './types';
import { createPendingElicitation } from './elicitation-store';

// Allow streaming responses up to 30 seconds
export const maxDuration = 30;

export async function POST(req: Request) {
  const { messages }: { messages: MCPElicitationUIMessage[] } =
    await req.json();

  const stream = createUIMessageStream({
    originalMessages: messages,
    execute: async ({ writer }) => {
      return processMessages(messages, writer);
    },
  });

  return createUIMessageStreamResponse({ stream });
}

async function processMessages(
  messages: MCPElicitationUIMessage[],
  writer: any,
) {
  // Create MCP client with elicitation capabilities
  const mcpClient = await createMCPClient({
    transport: {
      type: 'sse',
      url: 'http://localhost:8085/sse',
    },
    capabilities: {
      elicitation: {},
    },
  });

  // Handle elicitation requests from the MCP server
  mcpClient.onElicitationRequest(ElicitationRequestSchema, async request => {
    const elicitationId = `elicit-${Date.now()}-${Math.random()
      .toString(36)
      .slice(2)}`;

    try {
      // Send elicitation request to the frontend
      writer.write({
        type: 'data-elicitation-request',
        id: elicitationId,
        data: {
          elicitationId,
          message: request.params.message,
          requestedSchema: request.params.requestedSchema,
        },
      });

      // Wait for the user's response (will be resolved via the /respond endpoint)
      const userResponse = await createPendingElicitation(elicitationId);

      // Return the response in the format expected by the MCP server
      return {
        action: userResponse.action,
        content:
          userResponse.action === 'accept' ? userResponse.content : undefined,
      };
    } catch (error) {
      // Return a declined response on error
      return {
        action: 'decline' as const,
      };
    }
  });

  try {
    const tools = await mcpClient.tools();

    const result = streamText({
      model: openai('gpt-6-luna'),
      tools,
      stopWhen: isStepCount(10),
      onStepFinish: async ({ toolResults }) => {
        if (toolResults.length > 0) {
          console.log('TOOL RESULTS:', JSON.stringify(toolResults, null, 2));
        }
      },
      instructions:
        'You are a helpful assistant. When asked to register a user, use the register_user tool.',
      messages: await convertToModelMessages(messages),
      onEnd: async () => {
        await mcpClient.close();
      },
    });

    writer.merge(
      toUIMessageStream({ stream: result.stream, originalMessages: messages }),
    );
  } catch (error) {
    console.error('Error processing messages:', error);
    await mcpClient.close();
    throw error;
  }
}

import { UIDataTypes, type UIMessage } from 'ai';
export type ElicitationAction = 'accept' | 'decline' | 'cancel';

export interface ElicitationRequest {
  id: string;
  message: string;
  requestedSchema: unknown;
}

export interface ElicitationResponse {
  id: string;
  action: ElicitationAction;
  content?: Record<string, unknown>;
}

// Define custom data types for elicitation
export type ElicitationDataTypes = {
  'elicitation-request': {
    elicitationId: string;
    message: string;
    requestedSchema: unknown;
  };
  'elicitation-response': {
    elicitationId: string;
    action: ElicitationAction;
    content?: Record<string, unknown>;
  };
};

// Define custom message type with elicitation data parts
export type MCPElicitationUIMessage = UIMessage<
  never, // metadata type
  ElicitationDataTypes,
  never // no tools in this example (all tools come from MCP)
>;

import { openai } from '@ai-sdk/openai';
import {
  convertToModelMessages,
  isStepCount,
  streamText,
  createUIMessageStream,
  createUIMessageStreamResponse,
  toUIMessageStream,
} from 'ai';
import {
  createMCPClient,
  auth,
  type OAuthClientInformation,
  type OAuthClientMetadata,
  type OAuthTokens,
} from '@ai-sdk/mcp';
import { createServer } from 'node:http';

type AuthGlobalState = {
  pendingAuthorizationUrl: string | null;
};

const AUTH_GLOBAL_KEY = '__mcpAuth';

function getAuthState(): AuthGlobalState {
  const g = globalThis as any;
  if (!g[AUTH_GLOBAL_KEY]) {
    g[AUTH_GLOBAL_KEY] = {
      pendingAuthorizationUrl: null,
    } as AuthGlobalState;
  }
  return g[AUTH_GLOBAL_KEY] as AuthGlobalState;
}

function setPendingAuthorizationUrl(url: string | null): void {
  getAuthState().pendingAuthorizationUrl = url;
}

// In-memory storage for OAuth state per server origin
const oauthStateStore = new Map<
  string,
  {
    tokens?: OAuthTokens;
    codeVerifier?: string;
    clientInformation?: OAuthClientInformation;
  }
>();

class InMemoryOAuthClientProvider {
  private serverOrigin: string;
  private _redirectUrl: string;

  constructor(serverUrl: string | URL, callbackPort: number) {
    this.serverOrigin = new URL(serverUrl).origin;
    this._redirectUrl = `http://localhost:${callbackPort}/callback`;
  }

  private getState() {
    if (!oauthStateStore.has(this.serverOrigin)) {
      oauthStateStore.set(this.serverOrigin, {});
    }
    return oauthStateStore.get(this.serverOrigin)!;
  }

  async tokens(): Promise<OAuthTokens | undefined> {
    return this.getState().tokens;
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    this.getState().tokens = tokens;
  }

  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    setPendingAuthorizationUrl(authorizationUrl.toString());
  }

  async saveCodeVerifier(codeVerifier: string): Promise<void> {
    this.getState().codeVerifier = codeVerifier;
  }

  async codeVerifier(): Promise<string> {
    const verifier = this.getState().codeVerifier;
    if (!verifier) throw new Error('No code verifier saved');
    return verifier;
  }

  get redirectUrl(): string | URL {
    return this._redirectUrl;
  }

  get clientMetadata(): OAuthClientMetadata {
    return {
      client_name: 'AI SDK MCP OAuth Example (Next.js)',
      redirect_uris: [String(this._redirectUrl)],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      token_endpoint_auth_method: 'client_secret_post',
    } as any;
  }

  async clientInformation(): Promise<OAuthClientInformation | undefined> {
    return this.getState().clientInformation;
  }

  async saveClientInformation(info: OAuthClientInformation): Promise<void> {
    this.getState().clientInformation = info;
  }

  addClientAuthentication = async (
    headers: Headers,
    params: URLSearchParams,
    _url: string | URL,
  ): Promise<void> => {
    const info = this.getState().clientInformation;
    if (!info) {
      return;
    }

    const method = (info as any).token_endpoint_auth_method as
      | 'client_secret_post'
      | 'client_secret_basic'
      | 'none'
      | undefined;

    const hasSecret = [REDACTED] as any).client_secret);
    const clientId = info.client_id;
    const clientSecret = (info as any).client_secret as string | undefined;

    const chosen = method ?? (hasSecret ? 'client_secret_post' : 'none');

    if (chosen === 'client_secret_basic') {
      if (!clientSecret) {
        params.set('client_id', clientId);
        return;
      }
      const credentials = Buffer.from(`${clientId}:${clientSecret}`).toString(
        'base64',
      );
      headers.set('Authorization', `Basic ${credentials}`);
      return;
    }

    if (chosen === 'client_secret_post') {
      params.set('client_id', clientId);
      if (clientSecret) params.set('client_secret', clientSecret);
      return;
    }

    params.set('client_id', clientId);
  };

  async invalidateCredentials(scope: 'all' | 'client' | 'tokens' | 'verifier') {
    const state = this.getState();
    if (scope === 'all' || scope === 'tokens') state.tokens = undefined;
    if (scope === 'all' || scope === 'client')
      state.clientInformation = undefined;
    if (scope === 'all' || scope === 'verifier') state.codeVerifier = undefined;
  }
}

function waitForAuthorizationCode(port: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const server = createServer((req, res) => {
      if (!req.url) {
        res.writeHead(400).end('Bad request');
        return;
      }
      const url = new URL(req.url, `http://localhost:${port}`);
      if (url.pathname !== '/callback') {
        res.writeHead(404).end('Not found');
        return;
      }
      const code = url.searchParams.get('code');
      const err = url.searchParams.get('error');
      if (code) {
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(
          '<html><body><h1>Authorization Successful</h1><p>You can close this window.</p><script>window.close();</script></body></html>',
        );
        setTimeout(() => server.close(), 100);
        resolve(code);
      } else {
        res
          .writeHead(400)
          .end(`Authorization failed: ${err ?? 'missing code'}`);
        setTimeout(() => server.close(), 100);
        reject(new Error(`Authorization failed: ${err ?? 'missing code'}`));
      }
    });
    server.listen(port, () => {
      console.log(`OAuth callback server: http://localhost:${port}/callback`);
    });
  });
}

export async function POST(req: Request) {
  const body = await req.json();
  const messages = body.messages;
  const serverUrl: string = 'https://mcp.vercel.com/';
  const callbackPort = 8090;

  try {
    const stream = createUIMessageStream({
      originalMessages: messages,
      execute: async ({ writer }) => {
        const authProvider = new InMemoryOAuthClientProvider(
          serverUrl,
          callbackPort,
        );

        // Attempt auth; if redirect is needed, instruct client to open URL, then wait and complete.
        const result = await auth(authProvider, {
          serverUrl: new URL(serverUrl),
        });

        if (result !== 'AUTHORIZED') {
          const url = getAuthState().pendingAuthorizationUrl;
          if (url) {
            writer.write({
              type: 'data-oauth',
              data: { url },
              transient: true,
            });
          }

          const authorizationCode =
            await waitForAuthorizationCode(callbackPort);
          await auth(authProvider, {
            serverUrl: new URL(serverUrl),
            authorizationCode,
          });
        }

        const mcpClient = await createMCPClient({
          transport: { type: 'http', url: serverUrl, authProvider },
        });

        try {
          const tools = await mcpClient.tools();

          const result = streamText({
            model: openai('gpt-6-luna'),
            tools,
            stopWhen: isStepCount(10),
            instructions:
              'You are a helpful assistant with access to protected tools.',
            messages: await convertToModelMessages(messages),
          });

          writer.merge(
            toUIMessageStream({
              stream: result.stream,
              originalMessages: messages,
            }),
          );
        } finally {
          await mcpClient.close();
        }
      },
    });

    return createUIMessageStreamResponse({ stream });
  } catch (error) {
    console.error('MCP with auth error:', error);
    return Response.json({ error: 'Unexpected error' }, { status: 500 });
  }
}

import { openaiImageGenerationCustomToolAgent } from '@/agent/openai/image-generation-custom-tool-agent';
import { createAgentUIStreamResponse } from 'ai';

export async function POST(request: Request) {
  const body = await request.json();

  console.dir(body.messages, { depth: Infinity });

  return createAgentUIStreamResponse({
    agent: openaiImageGenerationCustomToolAgent,
    uiMessages: body.messages,
  });
}

import { xaiMcpServerAgent } from '@/agent/xai/mcp-server-agent';
import { createAgentUIStreamResponse } from 'ai';

export async function POST(req: Request) {
  const { messages } = await req.json();

  return createAgentUIStreamResponse({
    agent: xaiMcpServerAgent,
    uiMessages: messages,
    sendSources: true,
  });
}

