import { describe, expect, it } from 'vitest';
import { bashCommandToInput, parseGitInvocation } from './parse-git-invocation';

describe('parseGitInvocation', () => {
  it('parses a clean single git invocation', () => {
    expect(parseGitInvocation('git status')).toEqual({
      subcommand: 'status',
      args: [],
    });
    expect(parseGitInvocation('git log --oneline -n 5')).toEqual({
      subcommand: 'log',
      args: ['--oneline', '-n', '5'],
    });
  });

  it('returns null for a bare git with no subcommand', () => {
    expect(parseGitInvocation('git')).toBeNull();
  });

  it('returns null for a non-git program', () => {
    expect(parseGitInvocation('ls -la')).toBeNull();
    expect(parseGitInvocation('/usr/bin/git status')).toBeNull();
  });

  it('fails closed on compound and obfuscated commands', () => {
    for (const command of [
      'cd /tmp && git clone https://x',
      'git status; git clone https://x',
      'git status | sh',
      'git $(echo clone) https://x',
      'git status `whoami`',
      'git status > /tmp/out',
      'git status \\\n clone',
    ]) {
      expect(parseGitInvocation(command)).toBeNull();
    }
  });
});

describe('bashCommandToInput', () => {
  it('maps a clean git command to a git action', () => {
    expect(bashCommandToInput('git clone https://x')).toEqual({
      kind: 'git',
      subcommand: 'clone',
      args: ['https://x'],
    });
  });

  it('maps anything unparseable to a bash action (policy denies by default)', () => {
    expect(bashCommandToInput('cd /tmp && git clone https://x')).toEqual({
      kind: 'bash',
      command: 'cd /tmp && git clone https://x',
    });
  });
});

import { describe, expect, it, vi } from 'vitest';
import { httpPolicyClient } from './http-policy-client';

// Simulate the peer dep being absent: any dynamic import of
// '@open-policy-agent/opa' is intercepted and rejected so the lazy-import
// fallback path in the client fires.
vi.mock('@open-policy-agent/opa', () => {
  throw new Error('intentional test failure: module unresolved');
});

describe('httpPolicyClient', () => {
  it('throws a clear install-as-peer-dep error when @open-policy-agent/opa is absent', async () => {
    const client = httpPolicyClient({ url: 'http://localhost:8181' });

    await expect(client.evaluate('p', {})).rejects.toThrow(
      /Cannot import "@open-policy-agent\/opa"\. Install it as a peer dependency/,
    );
  });

  it('attaches the underlying import error as `cause` (ES2018-safe)', async () => {
    const client = httpPolicyClient({ url: 'http://localhost:8181' });

    try {
      await client.evaluate('p', {});
      throw new Error('should have rejected');
    } catch (err) {
      expect(err).toBeInstanceOf(Error);
      expect((err as Error & { cause?: unknown }).cause).toBeDefined();
    }
  });

  it('only attempts the import lazily (constructor does not throw)', () => {
    expect(() =>
      httpPolicyClient({
        url: 'http://localhost:8181',
        headers: { Authorization: 'Bearer x' },
      }),
    ).not.toThrow();
  });
});

import { describe, expect, it } from 'vitest';
import { normalizeOpaDecision } from './normalize-opa-decision';

describe('normalizeOpaDecision', () => {
  describe('explicit decision form', () => {
    it('maps "allow" to approved', () => {
      expect(normalizeOpaDecision({ decision: 'allow' })).toEqual({
        type: 'approved',
      });
    });

    it('carries reason through on allow', () => {
      expect(
        normalizeOpaDecision({ decision: 'allow', reason: 'role match' }),
      ).toEqual({ type: 'approved', reason: 'role match' });
    });

    it('maps "deny" to denied with reason', () => {
      expect(
        normalizeOpaDecision({
          decision: 'deny',
          reason: 'pushes require approval',
        }),
      ).toEqual({ type: 'denied', reason: 'pushes require approval' });
    });

    it('maps "requires-approval" to user-approval', () => {
      expect(normalizeOpaDecision({ decision: 'requires-approval' })).toEqual({
        type: 'user-approval',
      });
    });

    it('carries reason through on requires-approval', () => {
      expect(
        normalizeOpaDecision({
          decision: 'requires-approval',
          reason: 'requires operator review',
        }),
      ).toEqual({
        type: 'user-approval',
        reason: 'requires operator review',
      });
    });

    it('maps "not-applicable" to not-applicable', () => {
      expect(normalizeOpaDecision({ decision: 'not-applicable' })).toEqual({
        type: 'not-applicable',
      });
    });
  });

  describe('legacy boolean form', () => {
    it('maps { allow: true } to approved', () => {
      expect(normalizeOpaDecision({ allow: true })).toEqual({
        type: 'approved',
      });
    });

    it('maps { allow: false, reason } to denied with reason', () => {
      expect(
        normalizeOpaDecision({ allow: false, reason: 'no rule matched' }),
      ).toEqual({ type: 'denied', reason: 'no rule matched' });
    });

    it('maps { allow: true, reason } to approved with reason', () => {
      expect(
        normalizeOpaDecision({ allow: true, reason: 'reviewer role' }),
      ).toEqual({ type: 'approved', reason: 'reviewer role' });
    });
  });

  describe('fallthrough', () => {
    it('treats null as not-applicable', () => {
      expect(normalizeOpaDecision(null)).toEqual({ type: 'not-applicable' });
    });

    it('treats undefined as not-applicable', () => {
      expect(normalizeOpaDecision(undefined)).toEqual({
        type: 'not-applicable',
      });
    });

    it.each([
      ['an unknown decision value', { decision: 'blocked' }],
      ['a non-boolean legacy value', { allow: 'false' }],
      ['an unknown key', { verdict: 'deny' }],
      ['an unexpected nested shape', { result: { decision: 'deny' } }],
      ['a primitive', 'yes'],
    ])('denies %s', (_description, result) => {
      expect(normalizeOpaDecision(result)).toEqual({
        type: 'denied',
        reason: 'unrecognized OPA policy decision',
      });
    });
  });
});

import { describe, expect, it, vi } from 'vitest';
import { wasmPolicyClient } from './wasm-policy-client';

// Provide a working `loadPolicy` so we can exercise the evaluate path. The
// loaded policy's `evaluate` returns whatever the test queues up.
let nextResults: Array<{ result: unknown }> = [];
vi.mock('@open-policy-agent/opa-wasm', () => ({
  loadPolicy: async () => ({
    evaluate: () => nextResults,
    setData: () => {},
  }),
}));

describe('wasmPolicyClient.evaluate', () => {
  it('returns the first entry result on a normal response', async () => {
    nextResults = [{ result: { decision: 'deny', reason: 'no' } }];
    const client = await wasmPolicyClient({ wasm: new Uint8Array() });

    await expect(client.evaluate('p', {})).resolves.toEqual({
      decision: 'deny',
      reason: 'no',
    });
  });

  it('throws when the policy produced no result (empty array) so callers fail closed', async () => {
    nextResults = [];
    const client = await wasmPolicyClient({ wasm: new Uint8Array() });

    await expect(client.evaluate('p', {})).rejects.toThrow(
      /produced no result/,
    );
  });

  it('preserves a legitimately falsy result rather than swallowing it', async () => {
    nextResults = [{ result: false }];
    const client = await wasmPolicyClient({ wasm: new Uint8Array() });

    await expect(client.evaluate('p', {})).resolves.toBe(false);
  });

  it('throws (not a TypeError) when a misbehaving bundle returns a non-array', async () => {
    nextResults = null as never;
    const client = await wasmPolicyClient({ wasm: new Uint8Array() });

    await expect(client.evaluate('p', {})).rejects.toThrow(
      /produced no result/,
    );
  });
});

